// Keep only the newest item and derive a stable idempotency key from it.
// That key is what stops a re-run of this workflow from posting twice.
const items = $input.all();
if (!items.length) { return []; }
const it = items[0].json;
const link = String(it.link || it.guid || '');
const published = String(it.pubDate || it.published || '');
const stamp = new Date(published || Date.now()).toISOString().slice(0, 16);
return [{
  json: {
    title: String(it.title || '').slice(0, 300),
    link,
    summary: String(it.contentSnippet || it.content || it.description || '').slice(0, 4000),
    published,
    idempotencyKey: 'rss:' + stamp + ':' + link.slice(-60),
  },
}];

